import json


def select_jobs(now, capacity, running, pending):
    # Account for both resources; protect the first blocked job.
    return {"start": [], "reserved": None, "rejected": []}


def visualize(now, capacity, running, pending):
    # Export the actual input state and decision, not a mock diagram.
    return json.dumps({})

