def job(id, cpu=1, ram=1, duration=2, priority=0, submitted=0):
    return dict(id=id, cpu=cpu, ram=ram, duration=duration, priority=priority, submitted=submitted)
cap = {"cpu": 4, "ram": 8}
p = select_jobs(0, cap, [], [job("a", 2, 5), job("b", 2, 4), job("c", 1, 3, duration=1)])
assert p["start"] == ["a", "c"], p
assert p["reserved"] == {"id": "b", "at": 2}, p

